// Viewport helpers
const BASE_VIEW = { x: 0, y: 0, w: 1000, h: 1000 };

export const MAP_ZOOM_MIN = 1;
export const MAP_ZOOM_MAX = 6;
export const MAP_ZOOM_STEP = 0.5;

export function getMapViewBox(zoom: number, panX = 0, panY = 0) {
  const w = BASE_VIEW.w / zoom;
  const h = BASE_VIEW.h / zoom;
  const cx = BASE_VIEW.x + BASE_VIEW.w / 2;
  const cy = BASE_VIEW.y + BASE_VIEW.h / 2;
  return { x: cx - w / 2 + panX, y: cy - h / 2 + panY, w, h };
}

export function moroccoMapViewBox(zoom: number, panX = 0, panY = 0): string {
  const { x, y, w, h } = getMapViewBox(zoom, panX, panY);
  return `${x} ${y} ${w} ${h}`;
}

export function clampMapPan(zoom: number, panX: number, panY: number) {
  if (zoom <= 1) return { x: 0, y: 0 };
  const w = BASE_VIEW.w / zoom;
  const h = BASE_VIEW.h / zoom;
  const maxPanX = Math.max(0, (BASE_VIEW.w - w) / 2 + 60);
  const maxPanY = Math.max(0, (BASE_VIEW.h - h) / 2 + 80);
  return {
    x: Math.max(-maxPanX, Math.min(maxPanX, panX)),
    y: Math.max(-maxPanY, Math.min(maxPanY, panY)),
  };
}

// Region pin component
function RegionPin({
  region,
  isSelected,
  isDimmed,
  hoveredId,
  label,
  onHover,
  onClick,
}: {
  region: MoroccoRegionData;
  isSelected: boolean;
  isDimmed: boolean;
  hoveredId: string | null;
  label: string;
  onHover: (id: string | null) => void;
  onClick: (r: MoroccoRegionData) => void;
}) {
  const { cx, cy } = region.pin;
  const isHovered = hoveredId === region.id;
  const r = isSelected ? 10 : isHovered ? 9 : 7;
  const opacity = isDimmed ? 0.2 : 1;

  return (
    <g
      style={{ cursor: 'pointer', opacity, transition: 'opacity 0.25s' }}
      onClick={() => onClick(region)}
      onMouseEnter={() => onHover(region.id)}
      onMouseLeave={() => onHover(null)}
    >
      {(isSelected || isHovered) && (
        <circle cx={cx} cy={cy} r={22} fill={region.color} opacity={isSelected ? 0.3 : 0.18} />
      )}
      <circle cx={cx} cy={cy} r={r + 2} fill="#fff" stroke="#64748b" strokeWidth={1} />
      <circle cx={cx} cy={cy} r={r} fill={isSelected ? '#dc2626' : region.color} />
      {isHovered && (
        <g style={{ pointerEvents: 'none' }}>
          <rect x={cx - 70} y={cy - 34} width={140} height={22} rx={5} fill="#0f172a" opacity={0.92} />
          <text x={cx} y={cy - 21} textAnchor="middle" fontSize="10" fill="#fff" fontWeight="600">
            {label.length > 24 ? label.slice(0, 22) + '…' : label}
          </text>
        </g>
      )}
    </g>
  );
}

// Main SVG component
export interface MoroccoMapSvgProps {
  regions: typeof import('../data/moroccoMapData').MOROCCO_MAP_REGIONS;
  selectedRegionId: string | null;
  activeRegionFilter: string | null;
  hoveredPin: string | null;
  lang: 'fr' | 'en' | 'ar';
  zoom?: number;
  panX?: number;
  panY?: number;
  regionLabel: (r: MoroccoRegionData) => string;
  onHover: (id: string | null) => void;
  onSelect: (r: MoroccoRegionData) => void;
  bgColor?: string;
  activeRegionIds?: string[] | null;
}

export default function MoroccoMapSvg({
  regions,
  selectedRegionId,
  activeRegionFilter,
  hoveredPin,
  lang: _lang,
  zoom = 1,
  panX = 0,
  panY = 0,
  regionLabel,
  onHover,
  onSelect,
  bgColor,
  activeRegionIds,
}: MoroccoMapSvgProps) {
  return (
    <svg
      viewBox={moroccoMapViewBox(zoom, panX, panY)}
      preserveAspectRatio="xMidYMid meet"
      className="w-full h-auto block select-none"
      style={{ maxHeight: '75vh' }}
      aria-label="Carte du Maroc"
    >
      <defs>
        <linearGradient id="atlGrad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#7ec8e3" />
          <stop offset="100%" stopColor="#3d8eb3" />
        </linearGradient>
        <filter id="landShadow" x="-3%" y="-3%" width="106%" height="106%">
          <feDropShadow dx="1" dy="2" stdDeviation="5" floodColor="#1e293b" floodOpacity="0.22" />
        </filter>
        <filter id="glow" x="-10%" y="-10%" width="120%" height="120%">
          <feDropShadow dx="0" dy="0" stdDeviation="4" floodColor="#fff" floodOpacity="0.6" />
        </filter>
        <pattern id="waves" width="40" height="8" patternUnits="userSpaceOnUse">
          <path d="M0 4 Q10 1 20 4 T40 4" fill="none" stroke="#fff" strokeWidth="0.6" opacity="0.1" />
        </pattern>
        <radialGradient id="vignette" cx="50%" cy="50%" r="70%">
          <stop offset="60%" stopColor="#000" stopOpacity="0" />
          <stop offset="100%" stopColor="#0c4a6e" stopOpacity="0.12" />
        </radialGradient>
      </defs>

      {/* Background (ocean) */}
      <rect x="-30" y="-20" width="1060" height="1060" fill={bgColor ?? 'url(#atlGrad)'} />
      {!bgColor && <rect x="-30" y="-20" width="1060" height="1060" fill="url(#waves)" />}

      {/* Morocco territory — colored regions with land shadow */}
      <g filter="url(#landShadow)">
        {regions.map((region) => {
          const pathD = REGION_PATHS[region.id];
          if (!pathD) return null;
          return (
            <path
              key={`shadow-${region.id}`}
              d={pathD}
              fill="#e5e7eb"
              stroke="none"
            />
          );
        })}
      </g>

      {/* Morocco territory — colored regions */}
      {regions.map((region) => {
        const pathD = REGION_PATHS[region.id];
        if (!pathD) return null;
        const isActive = !activeRegionFilter || activeRegionFilter === region.id;
        const isSel = selectedRegionId === region.id;
        const isHov = hoveredPin === region.id;
        const isDisabled = activeRegionIds != null && !activeRegionIds.includes(region.id);
        let fillOpacity = isActive ? 0.72 : 0.25;
        if (isSel) fillOpacity = 0.92;
        else if (isHov) fillOpacity = 0.85;
        if (isDisabled) fillOpacity = 0.9;

        return (
          <path
            key={`region-${region.id}`}
            d={pathD}
            fill={isDisabled ? '#d1d5db' : region.color}
            fillOpacity={fillOpacity}
            stroke="#fff"
            strokeWidth={isSel ? 2.5 : isHov ? 2 : 0.8}
            strokeOpacity={0.9}
            style={{
              cursor: isDisabled ? 'default' : 'pointer',
              transition: 'fill-opacity 0.2s, stroke-width 0.2s',
              filter: !isDisabled && (isSel || isHov) ? 'url(#glow)' : undefined,
            }}
            onClick={() => !isDisabled && onSelect(region)}
            onMouseEnter={() => !isDisabled && onHover(region.id)}
            onMouseLeave={() => onHover(null)}
          />
        );
      })}

      {/* Major cities */}
      {MAJOR_CITIES.map((city) => (
        <g key={city.id} style={{ pointerEvents: 'none' }}>
          <circle
            cx={city.x}
            cy={city.y}
            r={city.capital ? 6 : 4.5}
            fill={city.capital ? '#dc2626' : '#1e293b'}
            stroke="#fff"
            strokeWidth={1.5}
          />
          <text
            x={city.x + (city.x > 550 ? 10 : -10)}
            y={city.y + 1}
            textAnchor={city.x > 550 ? 'start' : 'end'}
            fontSize={city.capital ? 13 : 11}
            fontWeight={city.capital ? '800' : '600'}
            fill="#0f172a"
            stroke="#fff"
            strokeWidth={3}
            paintOrder="stroke"
            fontFamily="Arial, Helvetica, sans-serif"
          >
            {city.label}
          </text>
        </g>
      ))}

      {/* Compass */}
      <g transform="translate(80, 930)" opacity={0.8}>
        <circle r={16} fill="#fff" stroke="#64748b" strokeWidth={1} />
        <polygon points="0,-11 3,0 0,11 -3,0" fill="#dc2626" />
        <text y={26} textAnchor="middle" fontSize="10" fill="#475569" fontWeight="700">N</text>
      </g>

      {/* Scale bar */}
      <g transform="translate(130, 928)" opacity={0.75} style={{ pointerEvents: 'none' }}>
        <rect x="0" y="0" width="100" height="7" fill="#fff" rx="2" />
        <rect x="0" y="0" width="50" height="7" fill="#1e293b" rx="2" />
        <text x="0" y="-3" fontSize="8" fill="#fff">0</text>
        <text x="46" y="-3" fontSize="8" fill="#fff">250</text>
        <text x="92" y="-3" fontSize="8" fill="#fff">500 km</text>
      </g>

      {/* Vignette */}
      <rect x="-30" y="-20" width="1060" height="1060"
        fill="url(#vignette)" style={{ pointerEvents: 'none' }} />

      {/* Interactive region pins */}
      {regions.map((region) => (
        <RegionPin
          key={region.id}
          region={region}
          isSelected={selectedRegionId === region.id}
          isDimmed={!!activeRegionFilter && activeRegionFilter !== region.id}
          hoveredId={hoveredPin}
          label={regionLabel(region)}
          onHover={onHover}
          onClick={onSelect}
        />
      ))}
    </svg>
  );
}
